import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface DesignAnalysis {
  productTitle: string;
  category: string;
  targetAudience: string;
  psychologicalProfile: {
    mood: string;
    colorPalette: string[];
    emotionalImpact: string;
  };
  designStrategy: {
    lighting: string;
    background: string;
    composition: string;
    style: 'Minimalist' | 'Luxury' | 'Vibrant' | 'Corporate' | 'Organic';
  };
  imagePrompt: string;
}

export interface AppState {
  image: string | null;
  isAnalyzing: boolean;
  analysis: DesignAnalysis | null;
  error: string | null;
}

import { GoogleGenAI, Type } from "@google/genai";
import { DesignAnalysis } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const analyzeProductImage = async (base64Image: string): Promise<DesignAnalysis> => {
  const model = 'gemini-3-flash-preview';

  const systemInstruction = `You are a world-class Product Marketing Psychologist and Commercial Creative Director. 
  Your task is to analyze the product in the provided image and create a design strategy that maximizes consumer trust, luxury perception, and psychological appeal.

  Return the analysis in strict JSON format according to the provided schema. 
  All explanations should be in Bengali (বাংলা), but the technical "imagePrompt" for Midjourney/DALL-E must be in English for better accuracy.`;

  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        {
          inlineData: {
            mimeType: "image/jpeg",
            data: base64Image.split(',')[1]
          }
        },
        {
          text: "Analyze this product and provide a professional psychological design analysis and an image generation prompt."
        }
      ]
    },
    config: {
      systemInstruction,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          productTitle: { type: Type.STRING },
          category: { type: Type.STRING },
          targetAudience: { type: Type.STRING },
          psychologicalProfile: {
            type: Type.OBJECT,
            properties: {
              mood: { type: Type.STRING },
              colorPalette: { type: Type.ARRAY, items: { type: Type.STRING } },
              emotionalImpact: { type: Type.STRING }
            },
            required: ["mood", "colorPalette", "emotionalImpact"]
          },
          designStrategy: {
            type: Type.OBJECT,
            properties: {
              lighting: { type: Type.STRING },
              background: { type: Type.STRING },
              composition: { type: Type.STRING },
              style: { type: Type.STRING }
            },
            required: ["lighting", "background", "composition", "style"]
          },
          imagePrompt: { type: Type.STRING, description: "Midjourney style prompt in English" }
        },
        required: ["productTitle", "category", "targetAudience", "psychologicalProfile", "designStrategy", "imagePrompt"]
      }
    }
  });

  if (!response.text) {
    throw new Error("No response from AI");
  }

  return JSON.parse(response.text);
};

