          reader.readAsDataURL(file);
        });
      });

      Promise.all(readers).then(results => {
        setState(prev => ({ 
          ...prev, 
          images: [...prev.images, ...results].slice(0, 5), // Limit to 5 images
          analysis: null, 
          generatedImage: null, 
          error: null 
        }));
      });
    }
  };

