    { id: "9:16", label: "পোর্ট্রেট", icon: "M6 2h12v20H6V2z" },
    { id: "4:3", label: "স্ট্যান্ডার্ড", icon: "M3 5h18v14H3V5z" },
    { id: "3:4", label: "ভার্টিক্যাল", icon: "M5 3h14v18H5V3z" },
