import { GoogleGenAI, Type } from "@google/genai";
import { DesignAnalysis, PosterTheme } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeProductImage = async (
  productImages: string[], 
  referenceImages: string[], 
  userInstructions?: string
): Promise<DesignAnalysis> => {
  const model = 'gemini-3-flash-preview';

  const systemInstruction = `You are a world-class Product Marketing Psychologist and Commercial Creative Director. 
  You will receive images of a product. Analyze them and create a high-end design strategy.

  Return JSON in Bengali (except the imagePrompt which must be in English).`;

  const productParts = productImages.map(img => ({
    inlineData: { mimeType: "image/jpeg", data: img.split(',')[1] }
  }));

  const refParts = referenceImages.map(img => ({
    inlineData: { mimeType: "image/jpeg", data: img.split(',')[1] }
  }));

  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        { text: "PRODUCT IMAGES:" },
        ...productParts,
        ...(referenceImages.length > 0 ? [{ text: "STYLE REFERENCES:" }, ...refParts] : []),
        {
          text: `Analyze these images. ${userInstructions ? `User instructions: "${userInstructions}".` : ""} Provide a professional design strategy and a high-end commercial image prompt.`
        }
      ]
    },
    config: {
      systemInstruction,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          productTitle: { type: Type.STRING },
          category: { type: Type.STRING },
          targetAudience: { type: Type.STRING },
          psychologicalProfile: {
            type: Type.OBJECT,
            properties: {
              mood: { type: Type.STRING },
              colorPalette: { type: Type.ARRAY, items: { type: Type.STRING } },
              emotionalImpact: { type: Type.STRING }
            },
            required: ["mood", "colorPalette", "emotionalImpact"]
          },
          designStrategy: {
            type: Type.OBJECT,
            properties: {
              lighting: { type: Type.STRING },
              background: { type: Type.STRING },
              composition: { type: Type.STRING },
              style: { type: Type.STRING }
            },
            required: ["lighting", "background", "composition", "style"]
          },
          imagePrompt: { type: Type.STRING }
        },
        required: ["productTitle", "category", "targetAudience", "psychologicalProfile", "designStrategy", "imagePrompt"]
      }
    }
  });

  if (!response.text) throw new Error("No response from AI");
  return JSON.parse(response.text);
};

export const generateProductVision = async (
  prompt: string, 
  productImages: string[], 
  referenceImages: string[],
  aspectRatio: string = "1:1"
): Promise<string> => {
  const model = 'gemini-2.5-flash-image';

  const productParts = productImages.map(img => ({
    inlineData: { mimeType: "image/jpeg", data: img.split(',')[1] }
  }));

  const refParts = referenceImages.map(img => ({
    inlineData: { mimeType: "image/jpeg", data: img.split(',')[1] }
  }));

  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        ...productParts,
        ...(referenceImages.length > 0 ? [...refParts] : []),
        {
          text: `Generate an elite professional commercial shot based on this prompt: ${prompt}. Focus on lighting and high-end aesthetics.`
        }
      ]
    },
    config: {
      imageConfig: {
        aspectRatio: aspectRatio as any
      }
    }
  });

  const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
  if (!imagePart || !imagePart.inlineData) {
    throw new Error("Failed to generate vision");
  }

  return `data:image/png;base64,${imagePart.inlineData.data}`;
};

export const generateProductPoster = async (
  base64Image: string,
  analysis: DesignAnalysis,
  posterInstructions: string,
  theme: PosterTheme = 'Streetwear',
  aspectRatio: string = "9:16"
): Promise<string> => {
  const model = 'gemini-2.5-flash-image';

  let graphicStyle = "";
  switch(theme) {
    case 'Streetwear':
      graphicStyle = "Futuristic Streetwear Aesthetic. Add glass-morphism panels, barcode graphics, technical data overlays, complex info-graphic cards, and glowing typography. Dark high-tech mood.";
      break;
    case 'Editorial':
      graphicStyle = "Minimalist Editorial Layout. Add circular text paths, elegant white-space branding, fine lines, premium serif typography, and sophisticated floating product info badges.";
      break;
    case 'Magazine':
      graphicStyle = "High-End Fashion Magazine Cover. Add a huge bold 'HOODIE' or BRAND header, structured column text, color swatches chips, and premium magazine-style copy overlays.";
      break;
    case 'Urban':
      graphicStyle = "Gritty Urban/Destiny Aesthetic. Bold distorted typography, spray-paint textures, heavy contrast, grunge overlays, and raw underground branding style.";
      break;
  }

  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        {
          inlineData: {
            mimeType: "image/png",
            data: base64Image.split(',')[1]
          }
        },
        {
          text: `You are a world-class Graphic Designer at an elite advertising agency. 
          Transform the provided product photo into a MASTERPIECE COMMERCIAL POSTER.

          STYLE DIRECTION: ${graphicStyle}
          BRAND/PRODUCT NAME: "${analysis.productTitle}"
          USER INFO TO INTEGRATE: "${posterInstructions}"

          MANDATORY ELEMENTS:
          1. Maintain the product identity from the photo perfectly.
          2. Use complex layering: Add foreground and background graphic design elements.
          3. Integrate the User Info using professional typography (English).
          4. Add secondary graphic details like "New Collection 2026", "Premium Quality", and price tags in a design-forward way.
          5. The final output must look like a high-budget social media campaign asset.`
        }
      ]
    },
    config: {
      imageConfig: {
        aspectRatio: aspectRatio as any
      }
    }
  });

  const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
  if (!imagePart || !imagePart.inlineData) {
    throw new Error("Failed to generate poster");
  }

  return `data:image/png;base64,${imagePart.inlineData.data}`;
};

import React, { useState, useRef } from 'react';
import Header from './components/Header';
import { analyzeProductImage, generateProductVision, generateProductPoster } from './services/geminiService';
import { AppState, PosterTheme } from './types';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    productImages: [],
    referenceImages: [],
    aspectRatio: "1:1",
    customInstructions: "",
    posterInstructions: "",
    posterTheme: "Streetwear",
    isAnalyzing: false,
    isGeneratingImage: false,
    isGeneratingPoster: false,
    analysis: null,
    generatedImage: null,
    generatedPoster: null,
    error: null,
  });

  const productInputRef = useRef<HTMLInputElement>(null);
  const refInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>, type: 'product' | 'ref') => {
    const files = Array.from(e.target.files || []);
    if (files.length > 0) {
      const readers = files.map((file: any) => {
        return new Promise<string>((resolve) => {
          const reader = new FileReader();
          reader.onloadend = () => resolve(reader.result as string);
          reader.readAsDataURL(file);
        });
      });

      Promise.all(readers).then(results => {
        setState(prev => ({ 
          ...prev, 
          [type === 'product' ? 'productImages' : 'referenceImages']: [...prev[type === 'product' ? 'productImages' : 'referenceImages'], ...results].slice(0, 3),
          analysis: null, 
          generatedImage: null, 
          generatedPoster: null,
          error: null 
        }));
      });
    }
  };

  const removeImage = (index: number, type: 'product' | 'ref') => {
    setState(prev => ({
      ...prev,
      [type === 'product' ? 'productImages' : 'referenceImages']: prev[type === 'product' ? 'productImages' : 'referenceImages'].filter((_, i) => i !== index),
      analysis: null,
      generatedImage: null,
      generatedPoster: null
    }));
  };

  const handleProcess = async () => {
    if (state.productImages.length === 0) {
      setState(prev => ({ ...prev, error: "অনুগ্রহ করে অন্তত একটি প্রোডাক্টের ছবি আপলোড করুন।" }));
      return;
    }

    setState(prev => ({ ...prev, isAnalyzing: true, error: null, analysis: null, generatedImage: null, generatedPoster: null }));

    try {
      const analysisResult = await analyzeProductImage(state.productImages, state.referenceImages, state.customInstructions);
      setState(prev => ({ ...prev, analysis: analysisResult, isAnalyzing: false, isGeneratingImage: true }));

      const visionResult = await generateProductVision(analysisResult.imagePrompt, state.productImages, state.referenceImages, state.aspectRatio);
      setState(prev => ({ ...prev, generatedImage: visionResult, isGeneratingImage: false }));

    } catch (err) {
      console.error(err);
      setState(prev => ({ 
        ...prev, 
        isAnalyzing: false, 
        isGeneratingImage: false, 
        error: "প্রসেস করার সময় সমস্যা হয়েছে। আবার চেষ্টা করুন।" 
      }));
    }
  };

  const handleCreatePoster = async () => {
    if (!state.generatedImage || !state.analysis) return;

    setState(prev => ({ ...prev, isGeneratingPoster: true, error: null }));

    try {
      const posterResult = await generateProductPoster(
        state.generatedImage, 
        state.analysis, 
        state.posterInstructions,
        state.posterTheme,
        "9:16"
      );
      setState(prev => ({ ...prev, generatedPoster: posterResult, isGeneratingPoster: false }));
    } catch (err) {
      console.error(err);
      setState(prev => ({ 
        ...prev, 
        isGeneratingPoster: false, 
        error: "পোস্টার তৈরি করতে সমস্যা হয়েছে।" 
      }));
    }
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    alert("প্রম্পট কপি করা হয়েছে!");
