import { GoogleGenAI, Type } from "@google/genai";
import { DesignAnalysis, PosterTheme } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeProductImage = async (
  productImages: string[], 
  referenceImages: string[], 
  userInstructions?: string
): Promise<DesignAnalysis> => {
  const model = 'gemini-3-flash-preview';

  const systemInstruction = `You are an elite Global Creative Director and Consumer Psychologist.
  Your goal is to perform a Deep Visual & Psychological Analysis of the product to create a "Premium Brand Identity".

  IMPORTANT: You will also be provided with STYLE REFERENCES. You MUST analyze the aesthetic, lighting, and composition of these references and incorporate their soul into the output.

  ANALYSIS CRITERIA:
  1. Psychological Mood: Define an atmosphere (e.g., "High-Society Minimalism", "Gritty Urban Rebellion").
  2. Style Extraction: Identify specific elements from the STYLE REFERENCES (e.g., "Soft hazy lighting", "Dynamic high-angle composition", "Monochromatic palette").
  3. Visual Hierarchy: Suggest a composition that screams "Premium".

  IMAGE PROMPT (English): Create an ultra-detailed photographic prompt. Use the STYLE REFERENCES as a primary guide for the look and feel while keeping the product's identity from the CLIENT PRODUCT SAMPLES. Include specific camera settings and high-end studio lighting.

  Return the analysis in JSON format. All descriptions (except imagePrompt) MUST be in Bengali (বাংলা).`;

  const productParts = productImages.map(img => ({
    inlineData: { mimeType: "image/jpeg", data: img.split(',')[1] }
  }));

  const refParts = referenceImages.map(img => ({
    inlineData: { mimeType: "image/jpeg", data: img.split(',')[1] }
  }));

  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        { text: "CLIENT PRODUCT SAMPLES (The target product):" },
        ...productParts,
        ...(referenceImages.length > 0 ? [{ text: "STYLE REFERENCES (Mimic this aesthetic perfectly):" }, ...refParts] : []),
        {
          text: `Conduct a premium psychological design analysis. ${userInstructions ? `User request: "${userInstructions}".` : ""} Ensure the generated prompt mimics the STYLE REFERENCES' visual quality and mood.`
        }
      ]
    },
    config: {
      systemInstruction,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          productTitle: { type: Type.STRING },
          category: { type: Type.STRING },
          targetAudience: { type: Type.STRING },
          psychologicalProfile: {
            type: Type.OBJECT,
            properties: {
              mood: { type: Type.STRING },
              colorPalette: { type: Type.ARRAY, items: { type: Type.STRING } },
              lightingAtmosphere: { type: Type.STRING },
              emotionalImpact: { type: Type.STRING }
            },
            required: ["mood", "colorPalette", "lightingAtmosphere", "emotionalImpact"]
          },
          designStrategy: {
            type: Type.OBJECT,
            properties: {
              backgroundConcept: { type: Type.STRING },
              compositionRule: { type: Type.STRING },
              materialTextureFocus: { type: Type.STRING },
              style: { type: Type.STRING }
            },
            required: ["backgroundConcept", "compositionRule", "materialTextureFocus", "style"]
          },
          imagePrompt: { type: Type.STRING }
        },
        required: ["productTitle", "category", "targetAudience", "psychologicalProfile", "designStrategy", "imagePrompt"]
      }
    }
  });

  if (!response.text) throw new Error("No response from AI");
  return JSON.parse(response.text);
};

export const generateProductVision = async (
  prompt: string, 
  productImages: string[], 
  referenceImages: string[],
  aspectRatio: string = "1:1"
): Promise<string> => {
  const model = 'gemini-2.5-flash-image';

  const productParts = productImages.map(img => ({
    inlineData: { mimeType: "image/jpeg", data: img.split(',')[1] }
  }));

  const refParts = referenceImages.map(img => ({
    inlineData: { mimeType: "image/jpeg", data: img.split(',')[1] }
  }));

  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        ...productParts,
        ...(referenceImages.length > 0 ? [{ text: "STYLE VIBE TO REPLICATE:" }, ...refParts] : []),
        {
          text: `ACT AS A MASTER PHOTOGRAPHER. Generate a hyper-realistic commercial photo. 
          PROMPT: ${prompt}.
          MANDATORY: Mimic the lighting, depth of field, and general 'soul' of the STYLE VIBE images provided.
          Maintain the product from the original photos exactly.`
        }
      ]
    },
    config: {
      imageConfig: {
        aspectRatio: aspectRatio as any
      }
    }
  });

  const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
  if (!imagePart || !imagePart.inlineData) {
    throw new Error("Failed to generate premium vision");
  }

  return `data:image/png;base64,${imagePart.inlineData.data}`;
};

export const generateProductPoster = async (
  base64Image: string,
  analysis: DesignAnalysis,
  posterInstructions: string,
  theme: PosterTheme = 'Streetwear',
  aspectRatio: string = "9:16",
  referenceImages: string[] = [] // New parameter to help mimic layout style
): Promise<string> => {
  const model = 'gemini-2.5-flash-image';

  let designDirectives = "";
  switch(theme) {
    case 'Streetwear':
      designDirectives = "Futuristic Streetwear Aesthetic. Overlay technical barcodes, technical data cards, glass-morphism UI panels, and bold neo-tokyo typography.";
      break;
    case 'Editorial':
      designDirectives = "High-End Editorial Minimalism. Add circular branding text, thin architectural lines, sophisticated serif fonts, and plenty of negative space.";
      break;
    case 'Magazine':
      designDirectives = "Premium Fashion Magazine Layout. Add a massive bold title, structured typographic columns, and designer color-swatch elements.";
      break;
    case 'Urban':
      designDirectives = "Gritty Urban Rebellion Style. Use distorted bold typography, spray-textured overlays, and raw industrial branding elements.";
      break;
  }

  const refParts = referenceImages.map(img => ({
    inlineData: { mimeType: "image/jpeg", data: img.split(',')[1] }
  }));

  const response = await ai.models.generateContent({
    model,
    contents: {
      parts: [
        {
          inlineData: {
            mimeType: "image/png",
            data: base64Image.split(',')[1]
          }
        },
        ...(referenceImages.length > 0 ? [{ text: "MIMIC THE GRAPHIC DESIGN LAYOUT OF THESE REFERENCES:" }, ...refParts] : []),
        {
          text: `ACT AS A LEAD GRAPHIC DESIGNER. 
          Transform this product shot into a world-class finished poster.

          THEME: ${designDirectives}
          USER DATA TO INCLUDE: "${posterInstructions}"

          INSTRUCTIONS:
          1. If references are provided, study their text placement, typography styles, and graphic overlays. Mimic that 'Agency' level layout.
          2. Incorporate the User Data using professional typography.
          3. Add small premium details like "New Arrival 2026", "Auth Tech", or price badges.
          4. The result must be a high-fidelity, polished marketing asset.`
        }
      ]
    },
    config: {
      imageConfig: {
        aspectRatio: aspectRatio as any
      }
    }
  });

  const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
  if (!imagePart || !imagePart.inlineData) {
    throw new Error("Failed to generate elite poster");
  }

  return `data:image/png;base64,${imagePart.inlineData.data}`;
};

